const input = $input.first().json;
let raw = input.output || input.text || input.content || '';

raw = String(raw).replace(/```json/g, '').replace(/```/g, '').trim();
const match = raw.match(/\{[\s\S]*\}/);
const jsonString = match ? match[0] : raw;

let tx = {};
try {
  tx = JSON.parse(jsonString);
} catch (e) {
  tx = {};
}

const whatsappNumber = $('WhatsApp Webhook').first().json.message?.from?.id || '1104381256';
const date = String(tx.Date || new Date().toISOString().slice(0, 10)).trim();
const month = date.slice(0, 7);

let rawType = String(tx.Type || 'expense').toLowerCase().trim();
let category = String(tx.Category || 'Other').trim();
let vendor = String(tx.Vendor || 'N/A').trim();
let product = String(tx.Product || vendor).trim();
let amount = Number(tx.Amount ?? 0);
let notes = String(tx.notes || '').trim();

// SAFEGUARD 1: SELF-TRANSFERS (Zerodha/Groww/Wallets/Self-UPI)
const transferKeywords = ['zerodha', 'groww', 'binance', 'wallet', 'paytm wallet', 'self transfer', 'to my account', 'savings to', 'fd deposit', 'ppf'];
const isSelfTransfer = transferKeywords.some(k => vendor.toLowerCase().includes(k) || product.toLowerCase().includes(k) || notes.toLowerCase().includes(k));

// SAFEGUARD 2: CREDIT CARD BILL PAYMENTS (Liability Settlement)
const ccBillKeywords = ['credit card bill', 'cc payment', 'card settlement', 'hdfc card bill', 'sbi card bill', 'icici card bill', 'cred'];
const isCCPayment = ccBillKeywords.some(k => category.toLowerCase().includes(k) || vendor.toLowerCase().includes(k) || product.toLowerCase().includes(k) || notes.toLowerCase().includes(k));

// SAFEGUARD 3: REFUNDS & RETURNS (Amazon/Flipkart/Swiggy refund)
const isRefund = ['refund', 'cashback', 'return', 'reversed', 'reversal'].some(k => product.toLowerCase().includes(k) || notes.toLowerCase().includes(k) || category.toLowerCase().includes(k));

// SAFEGUARD 4: BILL SPLIT / REIMBURSEMENT (Friends splitting a bill)
const isSplitReimbursement = ['split', 'reimbursement', 'reimbursed', 'settleup', 'shared bill'].some(k => notes.toLowerCase().includes(k) || product.toLowerCase().includes(k));

let finalType = 'expense';
if (isCCPayment) {
  finalType = 'transfer';
  category = 'Credit Card Settlement';
} else if (isSelfTransfer) {
  finalType = 'transfer';
  category = 'Self Transfer / Investment Deposit';
} else if (isRefund || isSplitReimbursement) {
  finalType = 'income'; // Handled as negative expense offset in calculation engine
  category = isRefund ? 'Refund / Return' : 'Bill Split Reimbursement';
} else if (['income', 'credit', 'salary', 'freelance', 'dividend'].some(k => rawType.includes(k))) {
  finalType = 'income';
} else if (['investment', 'invest', 'stocks', 'mutual fund', 'sip', 'gold'].some(k => rawType.includes(k))) {
  finalType = 'investment';
} else if (rawType.includes('transfer')) {
  finalType = 'transfer';
} else {
  finalType = 'expense';
}

const duplicateKey = `${whatsappNumber}|${date}|${finalType}|${category.toLowerCase()}|${vendor.toLowerCase()}|${amount}`;

return [{
  json: {
    whatsapp_number: String(whatsappNumber),
    Month: month,
    Date: date,
    Type: finalType,
    Category: category,
    Vendor: vendor,
    Product: product,
    Amount: amount,
    Currency: tx.Currency || 'INR',
    currency_symbol: tx.currency_symbol || '₹',
    notes: notes || `${vendor} ${product}`,
    duplicate_key: duplicateKey,
    source: 'telegram'
  }
}];
